'use client';
import {ActionForm,VendorMediaPicker,type MediaChoice} from '@/components/vendor-forms';import {updateRestaurant} from '@/app/vendor/actions';
export function RestaurantForm({restaurant,cuisineIds,cuisines,media}:{restaurant:Record<string,unknown>;cuisineIds:string[];cuisines:Array<{id:string;name:string}>;media:MediaChoice[]}){const id=String(restaurant.id);return <ActionForm action={updateRestaurant} submitLabel="Enregistrer les modifications"><section className="vendor-card"><h2>Identité et photos</h2><div className="vendor-photo-grid"><div><strong>Logo</strong><VendorMediaPicker restaurantId={id} type="logo" pathName="logo_path" initialPath={String(restaurant.logo_path??'')} items={media}/></div><div><strong>Couverture</strong><VendorMediaPicker restaurantId={id} type="cover" pathName="cover_path" initialPath={String(restaurant.cover_path??'')} items={media}/></div></div><div className="vendor-form-grid"><label className="field full"><span>Nom</span><input name="name" defaultValue={String(restaurant.name??'')} required/></label><label className="field full"><span>Description</span><textarea name="description" rows={4} defaultValue={String(restaurant.description??'')}/></label></div></section><section className="vendor-card"><h2>Contact et adresse</h2><div className="vendor-form-grid"><label className="field"><span>Téléphone</span><input name="phone" type="tel" defaultValue={String(restaurant.phone??'')}/></label><label className="field"><span>WhatsApp</span><input name="whatsapp" type="tel" defaultValue={String(restaurant.whatsapp??'')}/></label><label className="field full"><span>Email</span><input name="email" type="email" defaultValue={String(restaurant.email??'')}/></label><label className="field full"><span>Adresse</span><input name="address" defaultValue={String(restaurant.address??'')}/></label><label className="field"><span>Commune / zone</span><input name="commune" defaultValue={String(restaurant.commune??'')}/></label><label className="field"><span>Lien Maps <small>facultatif</small></span><input name="maps_url" type="url" defaultValue={String(restaurant.maps_url??'')}/></label><label className="field"><span>Latitude <small>facultatif</small></span><input name="latitude" type="number" step="any" defaultValue={String(restaurant.latitude??'')}/></label><label className="field"><span>Longitude <small>facultatif</small></span><input name="longitude" type="number" step="any" defaultValue={String(restaurant.longitude??'')}/></label></div></section><section className="vendor-card"><h2>Service</h2><label className="field prep-time"><span>Délai moyen de préparation</span><span><input name="average_prep_minutes" type="number" min="0" max="360" defaultValue={Number(restaurant.average_prep_minutes??25)}/><b>minutes</b></span></label><fieldset className="cuisine-choices"><legend>Types de cuisine</legend>{cuisines.map(cuisine=><label key={cuisine.id}><input type="checkbox" name="cuisine_ids" value={cuisine.id} defaultChecked={cuisineIds.includes(cuisine.id)}/><span>{cuisine.name}</span></label>)}</fieldset><div className="option-checks"><label><input type="checkbox" name="delivery_available" defaultChecked={Boolean(restaurant.delivery_available)}/><span>Livraison</span></label><label><input type="checkbox" name="pickup_available" defaultChecked={Boolean(restaurant.pickup_available)}/><span>Retrait</span></label></div></section></ActionForm>}
